using System.Collections.Generic;
using UnityEngine;
// Presentation only: commands still route through DungeonPrototype.Action.
public static class BattleUIArt {
 static readonly Dictionary<string,Texture2D> art=new Dictionary<string,Texture2D>();
 public static Texture2D Texture(string key){Texture2D t;if(!art.TryGetValue(key,out t))art[key]=t=Resources.Load<Texture2D>("UI/BattleUI/"+key);return t;}
 public static void Draw(Rect r,string key){var t=Texture(key);if(t==null)return;if(key=="Attack")GUI.DrawTextureWithTexCoords(r,t,new Rect(9f/370,3f/231,353f/370,144f/231),true);else if(key=="Item")GUI.DrawTextureWithTexCoords(r,t,new Rect(39f/404,7f/154,354f/404,140f/154),true);else GUI.DrawTexture(r,t,ScaleMode.StretchToFill,true);}
 static Rect Rel(Rect r,float x,float y,float w,float h){return new Rect(r.x+x*r.width,r.y+y*r.height,w*r.width,h*r.height);}
 static void Text(Rect r,string text,int size,Color color){var style=new GUIStyle(GUI.skin.label){fontSize=size,alignment=TextAnchor.MiddleLeft,clipping=TextClipping.Clip,padding=new RectOffset()};style.normal.textColor=color;while(style.fontSize>10&&style.CalcSize(new GUIContent(text)).x>r.width)style.fontSize--;GUI.Label(r,text,style);}
 public static void Player(Rect r,CombatPartyHudView data){Draw(r,"PlayerStatus");Text(Rel(r,.46f,.19f,.46f,.18f),data.name+"   LV "+data.level,19,NeonDungeonUI.Cyan);Text(Rel(r,.46f,.39f,.46f,.17f),"HP  "+data.hp+" / "+data.maximumHP,17,Color.white);var bar=Rel(r,.46f,.60f,.46f,.09f);NeonDungeonUI.Solid(bar,new Color(.12f,.02f,.10f));bar.width*=Mathf.Clamp01(data.hp/(float)Mathf.Max(1,data.maximumHP));NeonDungeonUI.Solid(bar,NeonDungeonUI.Pink);Text(Rel(r,.46f,.72f,.30f,.16f),"BITS "+data.bits+" / "+data.maximumBits,15,NeonDungeonUI.Cyan);bar=Rel(r,.75f,.76f,.17f,.07f);NeonDungeonUI.Solid(bar,new Color(.02f,.1f,.2f));bar.width*=Mathf.Clamp01(data.bits/(float)Mathf.Max(1,data.maximumBits));NeonDungeonUI.Solid(bar,NeonDungeonUI.Cyan);}
 public static void Enemy(Rect r,string label,int hp,int maximum,Texture2D portrait){Draw(r,"EnemyStatus");if(portrait!=null)GUI.DrawTexture(Rel(r,.065f,.22f,.18f,.55f),portrait,ScaleMode.ScaleToFit,true);Text(Rel(r,.29f,.23f,.61f,.24f),label,21,Color.white);var bar=Rel(r,.29f,.58f,.61f,.17f);NeonDungeonUI.Solid(bar,new Color(.12f,.02f,.10f));var fill=bar;fill.width*=Mathf.Clamp01(hp/(float)Mathf.Max(1,maximum));NeonDungeonUI.Solid(fill,NeonDungeonUI.Pink);Text(Rel(r,.29f,.45f,.6f,.14f),"HP "+Mathf.Max(0,hp)+" / "+maximum,15,Color.white);}
 public static bool Command(Rect r,string caption,string description,string key,bool selected,BattleUISettings settings){var color=GUI.color;GUI.color=GUI.enabled?(selected?new Color(1,.6f,.9f):Color.white):new Color(.45f,.45f,.5f);Draw(r,key);float top=key=="Attack"?.39f:key=="Hack"?.30f:.22f;if(selected)NeonDungeonUI.Solid(Rel(r,.48f,top+.51f,.43f,.025f),NeonDungeonUI.Pink);Text(Rel(r,.48f,top,.43f,.27f),caption,settings.commandFontSize,selected?Color.white:NeonDungeonUI.Cyan);Text(Rel(r,.48f,top+.27f,.43f,.20f),description,settings.descriptionFontSize,Color.white);GUI.color=color;return GUI.Button(r,GUIContent.none,GUIStyle.none);}
}
